pub fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both input vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Zip the two vectors together, compare element-wise, and collect the boolean results
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x != y)
     .collect()
}

